python3 - <<'VERIFYPY'
from topo_lex import topo_sort as t

assert t({}) == [], 'empty graph'
assert t({'a': []}) == ['a'], 'single node'
assert t({'a': ['b']}) == ['a', 'b'], 'simple edge'

# Successor-only nodes must appear.
assert sorted(t({'a': ['z']})) == ['a', 'z'], 'successor-only node missing'

# Lexicographically smallest among all valid orders.
g = {'b': ['c'], 'a': ['c'], 'c': []}
assert t(g) == ['a', 'b', 'c'], t(g)

g2 = {'z': ['y'], 'a': ['y'], 'y': [], 'b': []}
assert t(g2) == ['a', 'b', 'z', 'y'], t(g2)

g3 = {'a': ['b', 'c'], 'b': ['d'], 'c': ['d'], 'd': []}
assert t(g3) == ['a', 'b', 'c', 'd'], t(g3)

# Ties must resolve to the smaller name, not insertion order.
g4 = {'d': [], 'c': [], 'b': [], 'a': []}
assert t(g4) == ['a', 'b', 'c', 'd'], t(g4)

# Validity check on a wider graph: every edge respected.
g5 = {'m': ['n', 'o'], 'n': ['p'], 'o': ['p'], 'p': [], 'e': ['n']}
order = t(g5)
pos = {v: i for i, v in enumerate(order)}
for src, dsts in g5.items():
    for d in dsts:
        assert pos[src] < pos[d], 'edge %s->%s violated in %r' % (src, d, order)
assert order == ['e', 'm', 'n', 'o', 'p'], order

for cyc in [{'a': ['b'], 'b': ['a']}, {'a': ['a']}, {'a': ['b'], 'b': ['c'], 'c': ['a']}]:
    try:
        t(cyc)
        raise SystemExit('no ValueError for cycle %r' % (cyc,))
    except ValueError:
        pass
print('ok')
VERIFYPY
